function validate(input) {
  const [fn, calls] = input;
  if (!['sum', 'product', 'max', 'min'].includes(fn)) return 'fn must be "sum", "product", "max" or "min".';
  if (!Array.isArray(calls) || calls.length < 1 || calls.length > 10) return 'Give 1 to 10 calls.';
  if (JSON.stringify(calls).length > 1000) return 'calls must take at most 1000 characters as JSON.';
  for (const args of calls) {
    if (!Array.isArray(args) || args.length < 1 || args.length > 100) return 'Each call needs 1 to 100 arguments.';
    if (!args.every(x => Number.isInteger(x) && x >= -1000 && x <= 1000)) return 'Arguments must be integers from -1000 to 1000.';
    if (fn === 'product' && Math.abs(args.reduce((total, x) => total * x, 1)) > 1e15) return 'Each product must stay within 10^15 in absolute value.';
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [fnName, calls] = input;
  const operations = {
    sum: args => args.reduce((total, x) => total + x, 0),
    product: args => args.reduce((total, x) => total * x, 1) || 0,
    max: args => Math.max(...args),
    min: args => Math.min(...args),
  };
  let runs = 0;
  const fn = (...args) => {
    runs += 1;
    const value = operations[fnName](args);
    kit.trace(`fn(${args.join(', ')}) runs and returns ${value}`);
    return value;
  };
  const onceFn = solve(fn);
  if (typeof onceFn !== 'function') throw new Error('once must return a function.');
  const answer = [];
  for (const args of calls) {
    const before = runs;
    const value = onceFn(...args);
    kit.trace(`onceFn(${args.join(', ')}) returns ${value === undefined ? 'undefined' : JSON.stringify(value)}`);
    if (value !== undefined || runs > before) answer.push({ calls: runs, value: value === undefined ? null : value });
  }
  return answer;
}

