function generate(rand, size) {
  const names = ['sum', 'product', 'max', 'min'];
  const fn = names[Math.floor(rand() * names.length)];
  const count = size === 'small' ? 1 + Math.floor(rand() * 4) : 10;
  // A product of at most 20 numbers from -5 to 5 stays below 10^15.
  const longest = fn === 'product' ? 20 : size === 'small' ? 4 : 30;
  const top = fn === 'product' ? 5 : size === 'small' ? 10 : 1000;
  const calls = [];
  for (let i = 0; i < count; i++) {
    const length = 1 + Math.floor(rand() * longest);
    calls.push(Array.from({ length }, () => Math.floor(rand() * (2 * top + 1)) - top));
  }
  // Drop arguments from the end until the list fits in 1000 characters of JSON.
  while (JSON.stringify(calls).length > 1000) {
    const last = calls[calls.length - 1];
    if (last.length > 1) last.pop();
    else calls.pop();
  }
  return [fn, calls];
}
